/**
 * Signals in message BPSPackData.
 *
 * BPS pack electrical measurements: cell-sum and main/motor battery and precharge voltages, then battery current. Cell-voltage extrema are in BPSVoltageData; temperature summaries are in BPSTemperatureData. Signal encodings unchanged; no transmit period assigned yet.
 *
 * All signal values are as on the CAN bus.
 */
struct charger_can_raw_bps_pack_data_t {
    /**
     * Sum of the 32 cell-tap voltages, independent of precharge measurements. Bulk voltage encoding: unsigned 12 bits, 0.05 V/bit, offset 0 V.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t cell_sum_voltage;

    /**
     * MainBatteryVoltage
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t main_battery_voltage;

    /**
     * MotorBatteryVoltage
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t motor_battery_voltage;

    /**
     * MainVoltage
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t main_voltage;

    /**
     * MotorVoltage
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t motor_voltage;

    /**
     * BatteryCurrent
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t battery_current;

    /**
     * Age in milliseconds of the oldest continuous sensor sample included in this frame when assembled; saturates at 65535. Age must advance for cached samples. In a fault snapshot, freeze age at fault detection; per-channel captured ages, if present, remain authoritative for individual trip records.
     *
     * Range: -
     * Scale: 1
     * Offset: 0
     */
    uint16_t sample_age_ms;
};

